  [1307397] = { "罠が$N1個入ったTrapper's Workbenchを設置し、Camp Chairの効果もすべて得られます。近くにCampfireが必要です。\n\nCamp Chairの上に設置すると置き換えられます。\n\nすべての野営設備はクールダウン$D1を共有します。", nil, 0x6a4f5109, nil, "um" },
  [1307400] = { "Wrathがクリティカルになると、対象にかかっているInsect Swarmの効果時間が$N1秒延長されます。Beastsに対しては、さらに$N2秒延長されます。", nil, 0x7161a38a, nil, "um" },
  [1307411] = { "飲んでね。おいしいよ！", "羽のように体が軽く感じます……そして声がとても甲高くなっています！", 0xd0f4ad45, 0xc36d2ff6, "uu" },
  [1307423] = { "Goaz Warderを起動します。", nil, 0x3e261b23, nil, "um" },
  [1307508] = { "戦闘中に攻撃を受けると、攻撃者に$N1のNatureダメージと$N2のArcaneダメージを与えます。", "攻撃者に$N1のNatureダメージを与えます。", 0xcb88affa, 0xc2dcafc3, "uu" },
  [1307509] = { nil, "攻撃者に$N1のArcaneダメージを与えます。", nil, 0x7c47b36a, "mu" },
  [1307519] = { "$D1の間、自然の加護を呼び起こします。最初に近接攻撃を当ててきた敵は、$D2の間Rooted状態になります。", "次にあなたにMeleeダメージを与えた敵を絡め取ります。", 0x79b02591, 0x831fbd93, "uu" },
  [1307696] = { "対象に$N1のNatureダメージを与えます。DragonkinとWingedの敵には$N2倍のダメージを与えます。", nil, 0x583039a3, nil, "um" },
  [1307760] = { "インベントリがいっぱいの間、筋力が$N1増加します。", nil, 0x5a54dc97, nil, "um" },
  [1307792] = { "経験値を得られるDragonkinを倒すと、体力が$N1回復します。この効果は$N2秒に一度までしか発生しません。", nil, 0x73c05b1b, nil, "um" },
  [1307940] = { "対象に$N1のHolyダメージを与えます。アンデッドと悪魔には$N2倍のダメージを与えます。", nil, 0x6d51a01e, nil, "um" },
  [1307943] = { "Pick PocketとDistractアビリティの成功率を$N1%上昇させます。", nil, 0x3f291373, nil, "um" },
})
